// 특정 별자리의 관계 목록 조회 유틸
export function getRelationsByGrade(mansionId, grade) {
  const rels = RELATIONS[mansionId];
  if (!rels) return [];
  return Object.entries(rels)
    .filter(([_, v]) => v.등급 === grade)
    .map(([id, v]) => ({ id: Number(id), ...v }));
}

// 두 별자리 간 관계 조회
export function getRelation(idA, idB) {
  return RELATIONS[idA]?.[idB] ?? null;
}